// ============================================================
// Location Data — All 60 town/county location pages + 8 NJ county pages
// Each location has unique SEO-optimized content
// ============================================================

export interface LocationData {
  slug: string;
  name: string;
  state: string;
  stateAbbr: string;
  region: string;
  fullService: boolean; // NJ = full, out-of-state = limited
  description: string;
  industries: string[];
  caseStudy: {
    title: string;
    challenge: string;
    solution: string;
    results: string[];
  };
  nearbyAreas: string[];
  responseTime: string;
  serviceRadius: string;
  // ---- Optional rich content fields (parity with ServiceAreaTown) ----
  // All optional so existing (un-enriched) location data still compiles and
  // renders identically. Each corresponding section in LocationPage.tsx is
  // skipped when its field is undefined.
  heroTagline?: string;
  intro?: string;
  landmarks?: string[];
  neighborhoods?: string[];
  localContext?: string;
  spotlight?: { title: string; body: string };
  faqs?: { q: string; a: string }[];
  proximity?: string;
}

export interface CountyData {
  slug: string;
  name: string;
  state: string;
  stateAbbr: string;
  description: string;
  towns: string[];
  industries: string[];
  caseStudy: {
    title: string;
    challenge: string;
    solution: string;
    results: string[];
  };
  // ---- Optional rich content fields (parity with LocationData) ----
  // All optional so un-enriched county data still compiles and renders
  // identically. Each section in CountyPage.tsx is skipped when undefined.
  heroTagline?: string;
  intro?: string;
  landmarks?: string[];
  neighborhoods?: string[];
  localContext?: string;
  spotlight?: { title: string; body: string };
  faqs?: { q: string; a: string }[];
  proximity?: string;
}

// Helper to generate a slug from a location name
function toSlug(name: string, stateAbbr: string): string {
  return `${name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/-+$/, "")}-${stateAbbr.toLowerCase()}`;
}

