// Helper to get location by slug
export function getLocationBySlug(slug: string): LocationData | undefined {
  return ALL_LOCATIONS.find((loc) => loc.slug === slug);
}

// Helper to get county by slug
export function getCountyBySlug(slug: string): CountyData | undefined {
  return COUNTY_DATA.find((c) => c.slug === slug);
}

